// RSIOpen opens a live [RSIStream] on a warm-up history, oldest bar first, and
// returns it with its value at the last history bar, the value [Core.RSI]
// writes there.
//
// inReal is the history; the parameters are those of [Core.RSI].
//
// The error is [InsufficientHistory] for a history of at most
// [Core.RSILookback] bars, [OutOfRangeEndIndex] for one longer than
// [IndexMax]+1 bars, and [BadParam] for a parameter out of range.
func (c *Core) RSIOpen(inReal []float64, optInTimePeriod int) (*RSIStream, float64, error) {
	if !fitsInt32(optInTimePeriod) {
		return nil, 0, BadParam
	}
	sp, err := c.rsiOpenInternal(inReal, 0, int32(optInTimePeriod))
	if err != nil {
		return nil, 0, err
	}
	return sp, sp.cur_outReal, nil
}

// RSIOpenAndFill opens a stream as [Core.RSIOpen] does and also writes the
// outputs over the whole history, as [Core.RSI] writes them for bars 0 through
// len(inReal)-1, returning that range.
//
// Each output must hold len(inReal) minus [Core.RSILookback] values and share
// no memory with an input or another output.
//
// The errors are those of [Core.RSIOpen], and [BadParam] for an output that is
// empty, too short or sharing memory. A slice whose capacity a three-index
// expression cut, as slices.Clip does, can escape the sharing check.
func (c *Core) RSIOpenAndFill(inReal []float64, optInTimePeriod int, outReal []float64) (*RSIStream, OutRange, error) {
	if !fitsInt32(optInTimePeriod) {
		return nil, OutRange{}, BadParam
	}
	if len(inReal) > IndexMax+1 {
		return nil, OutRange{}, OutOfRangeEndIndex
	}
	lookback := int(c.rsiLookback(int32(optInTimePeriod)))
	if lookback < 0 {
		return nil, OutRange{}, BadParam
	}
	outLen := max(len(inReal)-lookback, 0)
	if len(outReal) == 0 || len(outReal) < outLen {
		return nil, OutRange{}, BadParam
	}
	if sameStart(outReal, inReal) {
		return nil, OutRange{}, BadParam
	}
	if outLen > 0 && overlaps(outReal, inReal) {
		return nil, OutRange{}, BadParam
	}
	var outBegIdx, outNBElement int32
	sp, err := c.rsiOpenAndFillInternal(inReal, 0, int32(optInTimePeriod), &outBegIdx, &outNBElement, outReal)
	if err != nil {
		return nil, OutRange{}, err
	}
	return sp, OutRange{BegIdx: int(outBegIdx), NBElement: int(outNBElement)}, nil
}
